-- ══ 4. 確認: 区分ごとのトピック数と行数 ══
DO $check$
DECLARE n_topics int; n_entries int;
BEGIN
  SELECT count(*) INTO n_topics FROM public.project_tech_topics WHERE project_id = 'p20';
  SELECT count(*) INTO n_entries FROM public.project_tech_entries WHERE project_id = 'p20';
  IF n_topics < 19 THEN RAISE EXCEPTION 'p20 topics expected >= 19, got %', n_topics; END IF;
  IF EXISTS (SELECT 1 FROM public.project_tech_topics WHERE project_id = 'p20' AND tech_domain = '磁気冷凍') THEN
    RAISE EXCEPTION 'p20 still has topics in the old domain';
  END IF;
  IF EXISTS (SELECT 1 FROM public.project_tech_entries WHERE project_id = 'p20' AND confidence = 'unverified' AND NOT needs_check) THEN
    RAISE EXCEPTION 'unverified row without needs_check';
  END IF;
  RAISE NOTICE 'p20 tech: % topics, % entries', n_topics, n_entries;
END
$check$;

COMMIT;
